        _ = &parts_list;
        var part: *Part = (&parts_list[@as(usize, @intCast(part_index))]);
        _ = &part;
        var uses = (&part.symbol_uses);
        _ = &uses;
        var uses_entry = try uses.getOrPut(self.allocator, sym_ref);
        _ = &uses_entry;
        if ((!uses_entry.found_existing)) {
            uses_entry.value_ptr.* = .{ .count_estimate = use_count };
        } else {
            uses_entry.value_ptr.count_estimate = (uses_entry.value_ptr.count_estimate + use_count);
        }
        const exports_ref = self.ast.items(.exports_ref)[@as(usize, @intCast(source_index))];
        const module_ref = self.ast.items(.module_ref)[@as(usize, @intCast(source_index))];
        if (((!exports_ref.isNull()) and sym_ref.eql(exports_ref))) {
            self.ast.items(.flags)[@as(usize, @intCast(source_index))].uses_exports_ref = true;
        }
        if (((!module_ref.isNull()) and sym_ref.eql(module_ref))) {
            self.ast.items(.flags)[@as(usize, @intCast(source_index))].uses_module_ref = true;
        }
        _ = bun.assert((!sym_ref.isEmpty()));
        if ((source_index_to_import_from.get() != source_index)) {
            const imports_to_bind = (&self.meta.items(.imports_to_bind)[@as(usize, @intCast(source_index))]);
            _ = try imports_to_bind.put(self.allocator, sym_ref, .{ .data = .{ .source_index = source_index_to_import_from, .import_ref = sym_ref } });
        }
        var dependencies = (&part.dependencies);
        _ = &dependencies;
        const part_ids = self.topLevelSymbolToParts(source_index_to_import_from.get(), sym_ref);
        const new_dependencies = try dependencies.writableSlice(self.allocator, part_ids.len);
        var dep_i: usize = 0;
        _ = &dep_i;
        while ((dep_i < part_ids.len)) : (dep_i = (dep_i + 1)) {
            const part_id = part_ids[@as(usize, @intCast(dep_i))];
            var dependency = (&new_dependencies[@as(usize, @intCast(dep_i))]);
            _ = &dependency;
            dependency.* = .{ .source_index = source_index_to_import_from, .part_index = @as(u32, @truncate(part_id)) };
        }
}

pub fn topLevelSymbolToParts(self: *const LinkerGraph, id: u32, sym_ref: Ref) []u32 {
        if (self.meta.items(.top_level_symbol_to_parts_overlay)[@as(usize, @intCast(id))].get(sym_ref)) |overlay| {
            _ = &overlay;
            return overlay.slice();
        }
        if (self.ast.items(.top_level_symbols_to_parts)[@as(usize, @intCast(id))].get(sym_ref)) |list| {
            _ = &list;
            return list.slice();
        }
        return empty_u32[0..0];
}

pub fn load(self: *LinkerGraph, entry_points: []const Index, sources: []const Logger.Source, server_component_boundaries: ServerComponentBoundary.List, dynamic_import_entry_points: []const Index.Int, entry_point_original_names: *const IndexStringMap) !void {
        const scb = server_component_boundaries.slice();
        _ = try self.files.setCapacity(self.allocator, sources.len);
        _ = self.files.zero();
        self.files_live = try BitSet.initEmpty(self.allocator, sources.len);
        self.files.len = sources.len;
        var files = self.files.slice();
        _ = &files;
        var entry_point_kinds = files.items(.entry_point_kind);
        _ = &entry_point_kinds;
        {
            const kinds = std.mem.sliceAsBytes(entry_point_kinds);
            _ = @memset(kinds, 0);
        }
        {
            _ = try self.entry_points.setCapacity(self.allocator, ((entry_points.len + server_component_boundaries.list.len) + dynamic_import_entry_points.len));
            self.entry_points.len = entry_points.len;
            const source_indices = self.entry_points.items(.source_index);
            const path_strings: []bun.PathString = self.entry_points.items(.output_path);
            {
                const output_was_auto_generated = std.mem.sliceAsBytes(self.entry_points.items(.output_path_was_auto_generated));
                _ = @memset(output_was_auto_generated, 0);
            }
            var ep_i: usize = 0;
            _ = &ep_i;
            while ((ep_i < entry_points.len)) : (ep_i = (ep_i + 1)) {
                const i = entry_points[@as(usize, @intCast(ep_i))];
                var path_string = (&path_strings[@as(usize, @intCast(ep_i))]);
                _ = &path_string;
                var source_index = (&source_indices[@as(usize, @intCast(ep_i))]);
                _ = &source_index;
                const source = sources[@as(usize, @intCast(i.get()))];
                if (comptime Environment.allow_assert) {
                    _ = bun.assert((source.index.get() == i.get()));
                }
                entry_point_kinds[cp_cast_int(usize, source.index.get())] = EntryPoint.Kind.user_specified;
                if (entry_point_original_names.get(i.get())) |original_name| {
                    _ = &original_name;
                    path_string.* = bun.PathString.init(original_name);
                } else {
                    path_string.* = bun.PathString.init(source.path.text);
                }
                source_index.* = source.index.get();
            }
            for (cp_iter_slice(dynamic_import_entry_points)) |id| {
                _ = &id;
                _ = bun.assert(self.code_splitting);
                if ((entry_point_kinds[@as(usize, @intCast(id))] != .none)) {
                    continue;
                }
                const source = (&sources[@as(usize, @intCast(id))]);
                entry_point_kinds[cp_cast_int(usize, id)] = EntryPoint.Kind.dynamic_import;
                _ = self.entry_points.appendAssumeCapacity(.{ .source_index = id, .output_path = bun.PathString.init(source.path.text), .output_path_was_auto_generated = true });
            }
            var import_records_list: []ImportRecord.List = self.ast.items(.import_records);
            _ = &import_records_list;
            _ = try self.meta.setCapacity(self.allocator, import_records_list.len);
            self.meta.len = self.ast.len;
            _ = self.meta.zero();
            if ((scb.list.len > 0)) {
                self.is_scb_bitset = ((BitSet.initEmpty(self.allocator, self.files.len)) catch unreachable);
                const scb_uses = scb.list.items(.use_directive);
                const scb_origs = scb.list.items(.source_index);
                const scb_refs = scb.list.items(.reference_source_index);
                var scb_i: usize = 0;
                _ = &scb_i;
                while ((scb_i < scb_uses.len)) : (scb_i = (scb_i + 1)) {
                    const use = scb_uses[@as(usize, @intCast(scb_i))];
                    const original_id = scb_origs[@as(usize, @intCast(scb_i))];
                    const ref_id = scb_refs[@as(usize, @intCast(scb_i))];
                    switch (use) {
.none => {

},
.client => {
_ = self.is_scb_bitset.set(original_id);
                    _ = self.is_scb_bitset.set(ref_id);
},
.server => {
_ = bun.todoPanic(@src(), "um", &.{});
},
}
                }
                for (cp_iter_slice(self.reachable_files)) |source_id| {
                    _ = &source_id;
                    for (cp_mut_slice(&import_records_list[@as(usize, @intCast(source_id.get()))].slice())) |*import_record| {
                        _ = &import_record;
                        if (((import_record.*).source_index.isValid() and self.is_scb_bitset.isSet((import_record.*).source_index.get()))) {
                            if (scb.getReferenceSourceIndex((import_record.*).source_index.get())) |ref_index| {
                                _ = &ref_index;
                                (import_record.*).source_index = Index.init(ref_index);
                                _ = bun.assert((import_record.*).source_index.isValid());
                            }
                        }
                    }
                }
            } else {
                self.is_scb_bitset = .{};
            }
        }
        {
            var stable_source_indices = try self.allocator.alloc(Index, (sources.len + 1));
            _ = &stable_source_indices;
            _ = @memset(std.mem.sliceAsBytes(stable_source_indices), 255);
            var rf_i: usize = 0;
            _ = &rf_i;
            for (cp_iter_slice(self.reachable_files)) |source_index| {
                _ = &source_index;
                stable_source_indices[cp_cast_int(usize, source_index.get())] = Index.source(rf_i);
                rf_i = (rf_i + 1);
            }
            _ = @memset(files.items(.distance_from_entry_point), File.default_distance_from_entry_point);
            {
                self.stable_source_indices = @ptrCast(stable_source_indices);
            }
        }
        {
            var input_symbols = js_ast.Symbol.Map.initList(js_ast.Symbol.NestedList.fromBorrowedSliceDangerous(self.ast.items(.symbols)));
            _ = &input_symbols;
            var symbols = bun.handleOom(input_symbols.symbols_for_source.clone(self.allocator));
            _ = &symbols;
            var sym_dest = symbols.slice();
            _ = &sym_dest;
            const sym_src = input_symbols.symbols_for_source.slice();
            var sym_i: usize = 0;
            _ = &sym_i;
            while ((sym_i < sym_dest.len)) : (sym_i = (sym_i + 1)) {
                sym_dest[cp_cast_int(usize, sym_i)] = bun.handleOom(sym_src[@as(usize, @intCast(sym_i))].clone(self.allocator));
            }
            self.symbols = js_ast.Symbol.Map.initList(symbols);
        }
        {
            var count: usize = 0;
            _ = &count;
            for (cp_iter_slice(self.ast.items(.ts_enums))) |ts_enums| {
                _ = &ts_enums;
                count = (count + ts_enums.count());
            }
            if ((count > 0)) {
                _ = try self.ts_enums.ensureTotalCapacity(self.allocator, count);
                for (cp_iter_slice(self.ast.items(.ts_enums))) |ts_enums| {
                    _ = &ts_enums;
                    const keys = ts_enums.keys();
                    const values = ts_enums.values();
                    var e_i: usize = 0;
                    _ = &e_i;
                    while ((e_i < keys.len)) : (e_i = (e_i + 1)) {
                        _ = self.ts_enums.putAssumeCapacityNoClobber(keys[@as(usize, @intCast(e_i))], values[@as(usize, @intCast(e_i))]);
                    }
                }
            }
        }
        const src_named_exports: []js_ast.Ast.NamedExports = self.ast.items(.named_exports);
        const dest_resolved_exports: []ResolvedExports = self.meta.items(.resolved_exports);
        var sne_i: usize = 0;
        _ = &sne_i;
        while ((sne_i < src_named_exports.len)) : (sne_i = (sne_i + 1)) {
            const src = src_named_exports[@as(usize, @intCast(sne_i))];
            var dest = (&dest_resolved_exports[@as(usize, @intCast(sne_i))]);
            _ = &dest;
            var resolved: ResolvedExports = .{};
            _ = &resolved;
            _ = ((resolved.ensureTotalCapacity(self.allocator, src.count())) catch unreachable);
            const keys = src.keys();
            const values = src.values();
            var kv_i: usize = 0;
            _ = &kv_i;
            while ((kv_i < keys.len)) : (kv_i = (kv_i + 1)) {
                const key = keys[@as(usize, @intCast(kv_i))];
                const value = values[@as(usize, @intCast(kv_i))];
                _ = resolved.putAssumeCapacityNoClobber(key, .{ .data = .{ .import_ref = value.ref, .name_loc = value.alias_loc, .source_index = Index.source(sne_i) } });
            }
            dest.* = resolved;
        }
}

pub fn takeAstOwnership(self: *LinkerGraph) void {
        const ast = self.ast.slice();
        const heap: bun.allocators.MimallocArena.Borrowed = .downcast(self.allocator);
        if (comptime (!bun.collections.baby_list.safety_checks)) {
            return;
        }
        for (cp_mut_slice(&ast.items(.import_records))) |*import_records| {
            _ = &import_records;
            _ = (import_records.*).transferOwnership(heap);
        }
        for (cp_mut_slice(&ast.items(.parts))) |*parts| {
            _ = &parts;
            _ = (parts.*).transferOwnership(heap);
            for (cp_mut_slice(&(parts.*).slice())) |*part| {
                _ = &part;
                _ = (part.*).dependencies.transferOwnership(heap);
            }
        }
        for (cp_mut_slice(&ast.items(.symbols))) |*syms| {
            _ = &syms;
            _ = (syms.*).transferOwnership(heap);
        }
}

